@Configuration
@EnableAsync
class AsyncConfig {}

@Service
class PowiadomieniaService {

    @Async
    public void wyslijEmail(String adresat) {
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        System.out.println("Wyslano do " + adresat + " na watku " + Thread.currentThread().getName());
    }
}

@SpringBootTest
class PowiadomieniaServiceTest {

    @Autowired
    PowiadomieniaService serwis;

    @Test
    void wywolanieWracaNatychmiast() {
        String watekTestu = Thread.currentThread().getName();
        Instant start = Instant.now();

        serwis.wyslijEmail("klient@example.com");

        Duration czasWywolania = Duration.between(start, Instant.now());
        assertThat(czasWywolania).isLessThan(Duration.ofMillis(50));
        // nazwa watku w logu metody bedzie inna niz watekTestu
    }
}

